pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function balanceOf(address owner) external view returns (uint256);
    function approve(address spender, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get some USDT tokens
        uint256 initialBalance = 1000 * 10**6; // USDT has 6 decimals
        deal(TARGET, attacker, initialBalance);

        // Label for debugging
        vm.label(TARGET, "TetherToken (USDT)");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Get initial balance
        uint256 initialAttackerBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialAttackerBalance);

        // Try transferring to ourselves
        // First, need to check if fees are enabled
        // Let's transfer a small amount to ourselves
        uint256 transferAmount = 100 * 10**6; // 100 USDT

        // Check contract state
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("paused()"));
        if (success) {
            bool paused = abi.decode(data, (bool));
            require(!paused, "Contract is paused");
        }

        // Transfer to self
        IERC20(TARGET).transfer(attacker, transferAmount);

        // Check new balance
        uint256 newBalance = IERC20(TARGET).balanceOf(attacker);
        console.log("Balance after self-transfer:", newBalance);

        // The oracle will check if balance increased
        require(newBalance > initialAttackerBalance, "Balance did not increase");
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

